import React from 'react'
import {Container, Row, Col} from 'react-bootstrap'

function Station({station_info}) {
  return (
    <Container>
        <Row>
            <Col md={12}> Train Name : {station_info["station_name"]} </Col>
        </Row>
    </Container>
  )
}

export default Station
